#!/usr/bin/env bash
# Regenerate deploy/tracker-db-initdb-configmap.yaml from the canonical DB
# scripts in src/main/resources/db/. The ConfigMap is mounted into the postgres
# container at /docker-entrypoint-initdb.d so the DB owns its own schema — the
# single source of truth for the SQL stays in src/, this just packages it for
# `podman kube play`. Run this whenever schema.sql / seed.sql / oracle-ro.sql
# change, and commit the regenerated file.
set -euo pipefail
cd "$(dirname "$0")/.."

out=deploy/tracker-db-initdb-configmap.yaml
db=src/main/resources/db

{
  echo "# GENERATED by deploy/gen-initdb-configmap.sh from ${db}/*.sql — do not edit by hand."
  echo "# Loaded by postgres in filename order (01-, 02-, 03-), mirroring the old compose mounts."
  echo "apiVersion: v1"
  echo "kind: ConfigMap"
  echo "metadata:"
  echo "  name: tracker-db-initdb"
  echo "data:"
  for pair in "01-schema.sql:schema.sql" "02-seed.sql:seed.sql" "03-oracle-ro.sql:oracle-ro.sql"; do
    key="${pair%%:*}"
    file="${pair##*:}"
    echo "  ${key}: |"
    sed 's/^/    /' "${db}/${file}"
  done
} > "$out"

echo "wrote $out"
